
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_lgap_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_lgap", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.451148332502567e+01, 9.084828334244885e+01, 8.583930258350537e+01, 7.913985565450301e+01, 7.045845906435235e+01, 5.970518583558155e+01, 4.721199016677222e+01, 3.394943001247830e+01, 2.152741626649055e+01, 1.167068557826046e+01, 5.236329953800451e+00, 2.551915067856722e+00, 1.915476167151148e+00, 1.275431742882525e+00, 6.520745889576782e-01, 2.551970232136085e-01, 6.713251002537959e-02, 7.565061637369423e-03, 3.445651429585771e-04, 4.319410000559445e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


